// Finite State Machine to search for message boundaries
module FSM(
  input clk,
  input reset,
  input [7:0] in,
  output reg [1:0] state,
  output reg done
);
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: if (in[3]) state <= 2'b01; else state <= 2'b00;
        2'b01: if (~in[3]) state <= 2'b10; else state <= 2'b01;
        2'b10: if (in[3]) state <= 2'b11; else state <= 2'b10;
        2'b11: begin state <= 2'b00; done <= 1'b1; end
      endcase
    end
  end
end

// Datapath to output the 24-bit (3-byte) message.
module Datapath(
  input clk,
  input reset,
  input [7:0] in,
  input [1:0] state,
  input done,
  output reg [23:0] out_bytes
);
  reg [7:0] bytes [0:2];
  integer i;
  always @(posedge clk) begin
    if (reset) out_bytes <= 24'h0;
    else begin
      if (state == 2'b11) begin
        for (i = 0; i < 3; i = i + 1) bytes[i] <= in;
        out_bytes <= {bytes[0], bytes[1], bytes[2]};
      end
    end
  end
end

